 87→// runCleanCurrentHead cleans session data for the current HEAD commit.
 88→func runCleanCurrentHead(ctx context.Context, cmd *cobra.Command, force, dryRun bool) error {
 89→	strat := GetStrategy(ctx)
 90→	w := cmd.OutOrStdout()
 91→
 92→	// Dry-run: show what would be cleaned
 93→	if dryRun {
 94→		return previewCurrentHead(ctx, w)
 95→	}
 96→
 97→	// Check for active sessions before cleaning
 98→	if !force {
 99→		activeSessions, err := activeSessionsOnCurrentHead(ctx)
100→		if err != nil {
101→			fmt.Fprintf(cmd.ErrOrStderr(), "Warning: could not check for active sessions: %v\n", err)
102→			fmt.Fprintln(cmd.ErrOrStderr(), "Use --force to override.")
103→			return nil
104→		}
105→		if len(activeSessions) > 0 {
106→			fmt.Fprintln(cmd.ErrOrStderr(), "Active sessions detected on current HEAD:")
107→			for _, s := range activeSessions {
108→				fmt.Fprintf(cmd.ErrOrStderr(), "  %s (phase: %s)\n", s.SessionID, s.Phase)
109→			}
110→			fmt.Fprintln(cmd.ErrOrStderr(), "Use --force to override or wait for sessions to finish.")
111→			return nil
112→		}
113→	}
114→
115→	// Prompt for confirmation
116→	if !force {
117→		var confirmed bool
118→
119→		form := NewAccessibleForm(
120→			huh.NewGroup(
121→				huh.NewConfirm().
122→					Title("Clean session data for current HEAD?").
123→					Value(&confirmed),
124→			),
125→		)
126→
127→		if err := form.Run(); err != nil {
128→			if errors.Is(err, huh.ErrUserAborted) {
129→				return nil
130→			}
131→			return fmt.Errorf("failed to get confirmation: %w", err)
132→		}
133→
134→		if !confirmed {
135→			return nil
136→		}
137→	}
138→
139→	if err := strat.Reset(ctx); err != nil {
140→		return fmt.Errorf("clean failed: %w", err)
141→	}
142→
143→	return nil
