276→func runCleanAllWithItems(ctx context.Context, w io.Writer, force, dryRun bool, items []strategy.CleanupItem, tempFiles []string) error {
277→	// Handle no items case
278→	if len(items) == 0 && len(tempFiles) == 0 {
