287→		case strategy.CleanupTypeShadowBranch:
288→			branches = append(branches, item)
289→		case strategy.CleanupTypeSessionState:
290→			states = append(states, item)
291→		case strategy.CleanupTypeCheckpoint:
292→			checkpoints = append(checkpoints, item)
293→		}
294→	}
