424→// listTempFiles returns files in .entire/tmp/ that are safe to delete,
425→// excluding files belonging to active sessions.
426→func listTempFiles(ctx context.Context) ([]string, error) {
427→	tmpDir, err := paths.AbsPath(ctx, paths.EntireTmpDir)
428→	if err != nil {
429→		return nil, fmt.Errorf("failed to get temp dir path: %w", err)
430→	}
431→
432→	entries, err := os.ReadDir(tmpDir)
433→	if os.IsNotExist(err) {
434→		return nil, nil
435→	}
436→	if err != nil {
437→		return nil, fmt.Errorf("failed to read temp dir: %w", err)
438→	}
439→
440→	// Build set of active session IDs to protect their temp files
441→	activeSessionIDs := make(map[string]bool)
442→	if states, listErr := strategy.ListSessionStates(ctx); listErr == nil {
443→		for _, state := range states {
444→			activeSessionIDs[state.SessionID] = true
445→		}
446→	}
447→
448→	var files []string
449→	for _, entry := range entries {
450→		if entry.IsDir() {
451→			continue
452→		}
453→		// Skip temp files belonging to active sessions (e.g., "session-id.json")
454→		name := entry.Name()
455→		sessionID := strings.TrimSuffix(name, ".json")
456→		if sessionID != name && activeSessionIDs[sessionID] {
457→			continue
458→		}
459→		files = append(files, name)
460→	}
461→	return files, nil
462→}
