464→// TempFileDeleteError contains a file name and the error that occurred during deletion.
465→type TempFileDeleteError struct {
466→	File string
467→	Err  error
468→}
469→
470→// deleteTempFiles removes all files in .entire/tmp/.
471→// Returns successfully deleted files and any failures with their error reasons.
472→func deleteTempFiles(ctx context.Context, files []string) (deleted []string, failed []TempFileDeleteError) {
473→	tmpDir, err := paths.AbsPath(ctx, paths.EntireTmpDir)
474→	if err != nil {
475→		// Can't get path - mark all as failed with the same error
476→		for _, file := range files {
477→			failed = append(failed, TempFileDeleteError{File: file, Err: err})
478→		}
479→		return nil, failed
480→	}
481→
482→	for _, file := range files {
483→		path := filepath.Join(tmpDir, file)
484→		if err := os.Remove(path); err != nil {
485→			failed = append(failed, TempFileDeleteError{File: file, Err: err})
486→		} else {
487→			deleted = append(deleted, file)
488→		}
489→	}
490→	return deleted, failed
491→}
