493→// activeSessionsOnCurrentHead returns sessions on the current HEAD
494→// that are in an active phase (ACTIVE).
495→func activeSessionsOnCurrentHead(ctx context.Context) ([]*session.State, error) {
496→	repo, err := openRepository(ctx)
497→	if err != nil {
498→		return nil, err
499→	}
500→
501→	head, err := repo.Head()
502→	if err != nil {
503→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
504→	}
505→	currentHead := head.Hash().String()
506→
507→	states, err := strategy.ListSessionStates(ctx)
508→	if err != nil {
509→		return nil, fmt.Errorf("failed to list session states: %w", err)
510→	}
511→
512→	var active []*session.State
513→	for _, state := range states {
514→		if state.BaseCommit != currentHead {
515→			continue
516→		}
517→		if state.Phase.IsActive() {
518→			active = append(active, state)
519→		}
520→	}
521→
522→	return active, nil
523→}
